public class PatternMatchingDemo {
    // Legacy approach: repetitive and noisy
    public static void printLegacy(Object obj) {
        if (obj instanceof String) {
            String s = (String) obj;
            System.out.println("Legacy string: " + s.toLowerCase());
        }
    }

    // Modern Java 16+ approach: clean, atomic, flow-scoped
    public static void printModern(Object obj) {
        // Pattern matching with compound condition
        if (obj instanceof String s && !s.isBlank()) {
            System.out.println("Modern string: " + s.toLowerCase());
        } else if (obj instanceof Integer num && num > 0) {
            System.out.println("Positive integer: " + num);
        }
    }

    public static void main(String[] args) {
        printLegacy("HELLO LEGACY");
        printModern("HELLO MODERN");
        printModern(42);
    }
}

