import java.util.Objects;

class UserProfile {
    private String username;
    private String email;

    public UserProfile(String username, String email) {
        this.username = username;
        this.email = email;
    }

    @Override
    public boolean equals(Object obj) {
        // Identity check
        if (this == obj) return true;
        // Modern pattern matching handles null and type check in one line
        if (obj instanceof UserProfile other) {
            return Objects.equals(this.username, other.username) &&
                   Objects.equals(this.email, other.email);
        }
        return false;
    }

    @Override
    public int hashCode() {
        return Objects.hash(username, email);
    }
}

public class EqualsPatternDemo {
    public static void main(String[] args) {
        UserProfile u1 = new UserProfile("munafe", "munaf@example.com");
        UserProfile u2 = new UserProfile("munafe", "munaf@example.com");
        UserProfile u3 = new UserProfile("alice", "alice@example.com");

        System.out.println("u1 equals u2: " + u1.equals(u2)); // true
        System.out.println("u1 equals u3: " + u1.equals(u3)); // false
        System.out.println("u1 equals null: " + u1.equals(null)); // false
    }
}

