public class PatternApp {
    public static String formatObject(Object obj) {
        if (obj instanceof String s) {
            return "String: " + s.toUpperCase();
        } else if (obj instanceof Integer i) {
            return "Int: " + (i * 10);
        }
        return "Unknown";
    }

    public static void main(String[] args) {
        System.out.println(formatObject("java"));
        System.out.println(formatObject(5));
        System.out.println(formatObject(3.14));
    }
}

public class ValidatorApp {
    public static void validateInput(Object input) {
        if (input instanceof String s && s.length() >= 5) {
            System.out.println("Valid long string: " + s);
        } else if (input instanceof String s && s.length() < 5) {
            System.out.println("Short string rejected: " + s);
        } else if (input instanceof Double d && d > 0.0) {
            System.out.println("Positive double: " + d);
        } else {
            System.out.println("Unsupported input");
        }
    }

    public static void main(String[] args) {
        validateInput("Administrator");
        validateInput("Cat");
        validateInput(99.5);
        validateInput(-4.2);
    }
}

class SecureMessage {
    private String sender;
    private String content;
    public SecureMessage(String sender, String content) {
        this.sender = sender;
        this.content = content;
    }
    public String getSender() { return sender; }
    public String getContent() { return content; }
}

class MessageProcessor {
    public static void process(Object raw) {
        if (!(raw instanceof SecureMessage msg)) {
            System.out.println("Error: Not a secure message");
            return;
        }
        // msg is in scope here because the method returns if not SecureMessage!
        System.out.println("Processing message from " + msg.getSender() + ": " + msg.getContent());
    }
}

public class GuardApp {
    public static void main(String[] args) {
        MessageProcessor.process(new SecureMessage("Alice", "Top secret payload"));
        MessageProcessor.process("Just a plain string");
    }
}

