public class OrOperatorBug {
    public static void checkToken(Object obj) {
        // BUG: In Java, || is illegal with pattern variables because s would be unbound!
        // if (obj instanceof String s || s.isEmpty()) ...
        if (obj instanceof String s && !s.isEmpty()) {
            System.out.println("Valid token: " + s);
        } else {
            // Fix: handle Integer positive token as well
            System.out.println("Invalid token");
        }
    }

    public static void main(String[] args) {
        checkToken("AUTH-XYZ");
        checkToken("");
        checkToken(100); // Should print "Valid token: 100"
    }
}

