public class OrOperatorBug {
    public static void checkToken(Object obj) {
        if (obj instanceof String s && !s.isEmpty()) {
            System.out.println("Valid token: " + s);
        } else if (obj instanceof Integer i && i > 0) {
            System.out.println("Valid token: " + i);
        } else {
            System.out.println("Invalid token");
        }
    }

    public static void main(String[] args) {
        checkToken("AUTH-XYZ");
        checkToken("");
        checkToken(100);
    }
}

interface Expr {}

class Literal implements Expr {
    private double value;
    public Literal(double value) { this.value = value; }
    public double getValue() { return value; }
}

class Add implements Expr {
    private Expr left, right;
    public Add(Expr left, Expr right) { this.left = left; this.right = right; }
    public Expr getLeft() { return left; }
    public Expr getRight() { return right; }
}

class Multiply implements Expr {
    private Expr left, right;
    public Multiply(Expr left, Expr right) { this.left = left; this.right = right; }
    public Expr getLeft() { return left; }
    public Expr getRight() { return right; }
}

class Evaluator {
    public static double evaluate(Expr expr) {
        if (expr instanceof Literal lit) {
            return lit.getValue();
        } else if (expr instanceof Add add) {
            return evaluate(add.getLeft()) + evaluate(add.getRight());
        } else if (expr instanceof Multiply mul) {
            return evaluate(mul.getLeft()) * evaluate(mul.getRight());
        }
        throw new IllegalArgumentException("Unknown expr");
    }
}

public class ExpressionApp {
    public static void main(String[] args) {
        Expr expr = new Multiply(
            new Add(new Literal(3.0), new Literal(4.0)),
            new Literal(2.0)
        );
        System.out.println("Result: " + Evaluator.evaluate(expr));
    }
}
